from datetime import datetime, timedelta

class Scheduler:
    def __init__(self) -> None:
        self.appointments = {}  # appointment_id -> {'patient': str, 'doctor': str, 'start': datetime, 'end': datetime}
        self.next_id = 1
        self.patient_appointments = {}  # patient -> appointment_id of their upcoming appointment

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        # Requirement 5: Booking an appointment that starts before `now` raises ValueError
        if start < now:
            raise ValueError("Appointment cannot start before current time")

        # Requirement 1: A patient can have at most one upcoming appointment
        if patient in self.patient_appointments:
            existing_id = self.patient_appointments[patient]
            # Check if the existing appointment is still upcoming (not cancelled and start time > now)
            if existing_id in self.appointments:
                existing_app = self.appointments[existing_id]
                if existing_app['start'] > now:
                    raise ValueError("Patient already has an upcoming appointment")

        # Requirement 2: Booking an appointment that overlaps another appointment of the same doctor
        for appointment_id, appointment in self.appointments.items():
            if appointment['doctor'] == doctor:
                # Check for overlap: two intervals [a,b] and [c,d] overlap if a < d and c < b
                # Since touching (one ends when other starts) is allowed, we use strict inequalities
                if start < appointment['end'] and appointment['start'] < end:
                    raise ValueError("Doctor is not available during the requested time")

        # Create new appointment
        appointment_id = self.next_id
        self.next_id += 1

        self.appointments[appointment_id] = {
            'patient': patient,
            'doctor': doctor,
            'start': start,
            'end': end
        }

        self.patient_appointments[patient] = appointment_id

        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an appointment."""
        if appointment_id not in self.appointments:
            return  # Appointment doesn't exist, nothing to do

        appointment = self.appointments[appointment_id]

        # Requirement 4: Cancelling an appointment less than 24 hours before its start does not free the time slot
        # But we still need to remove it from patient's record if it's their current appointment
        if appointment['start'] - now >= timedelta(hours=24):
            # Cancelled with sufficient notice - remove from records
            del self.appointments[appointment_id]

            # Remove from patient's record if this was their appointment
            for patient, appt_id in list(self.patient_appointments.items()):
                if appt_id == appointment_id:
                    del self.patient_appointments[patient]
                    break
        # If cancelled with less than 24 hours notice, the appointment remains in self.appointments
        # but it's effectively cancelled (we don't track cancellation status separately)
        # However, the patient should no longer be associated with this appointment
        # since they can book a new one
        if appointment_id in self.appointments:
            # Remove patient association regardless of timing
            for patient, appt_id in list(self.patient_appointments.items()):
                if appt_id == appointment_id:
                    del self.patient_appointments[patient]
                    break

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        # Check all appointments for this doctor
        for appointment_id, appointment in self.appointments.items():
            if appointment['doctor'] == doctor:
                # Check for overlap: two intervals [a,b] and [c,d] overlap if a < d and c < b
                # Since touching is allowed, we use strict inequalities
                if start < appointment['end'] and appointment['start'] < end:
                    return False

        return True
